import asyncio

REGION = "us-west-2"

async def safe(coro):
    try:
        return await coro
    except Exception as e:
        code = None
        if hasattr(e, "response") and isinstance(e.response, dict):
            code = e.response.get("Error", {}).get("Code")
        return {"error": True, "code": code or type(e).__name__, "message": str(e)[:800]}

async def main():
    identity = await safe(call_boto3(service_name="sts", operation_name="get_caller_identity", region_name=REGION, params={}))
    return {"identity": identity}

result = asyncio.get_event_loop().run_until_complete(main())
result

